-- Montana. The state had one stop, and it is in this batch too.
--
-- The whole state is Mountain time, with no county exceptions.
--
-- Very well sourced: fwp.mt.gov leads by a distance, then visitmt.com, the BLM
-- and the Park Service. Almost no aggregators.
--
-- This batch arrived with spaced category names — "ghost town" rather than
-- "ghost-town" — and the parser rejected 106 of 120 stops outright. It refused
-- rather than skipping them, which is the whole reason it throws: an import
-- that stops dead is a five-minute fix, an import that quietly drops 106 rows
-- is a state that looks done and is not.
--
-- Spaces, capitals and ampersands are now all read, so "Indigenous history"
-- and "rock art & expedition history" work as written.
--
-- One proximity flag kept: the Great Plains Dinosaur Museum is 53 metres from
-- the Phillips County Museum because Malta has put both on the same block.
--
-- 119 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Bannack State Park', 'bannack-state-park', 'weird-history', 45.16068, -112.99422, 'Bannack', 'MT', 'Montana’s best-preserved territorial-era ghost town, with more than 50 historic structures lining the old main street. Buildings are interpreted rather than recreated, and winter access can be more limited.', 'open', 'https://fwp.mt.gov/stateparks/bannack', null, 'America/Denver', now()),
  ('Granite Ghost Town State Park', 'granite-ghost-town-state-park', 'weird-history', 46.31689, -113.24644, 'Philipsburg', 'MT', 'Ruins of the silver-boom city that once rose above Philipsburg, including the old Miners Union Hall and superintendent’s house. The approach is narrow, steep, and rough.', 'limited', 'https://fwp.mt.gov/stateparks/granite', null, 'America/Denver', now()),
  ('Elkhorn State Park', 'elkhorn-state-park', 'weird-history', 46.27514, -111.94619, 'Elkhorn', 'MT', 'A near-ghost town centered on two unusually ornate surviving frontier buildings, Fraternity Hall and Gillian Hall. Some nearby structures remain privately owned.', 'open', 'https://fwp.mt.gov/stateparks/elkhorn', null, 'America/Denver', now()),
  ('Coolidge Ghost Town', 'coolidge-ghost-town', 'weird-history', 45.4894, -113.0364, 'Wise River', 'MT', 'Remote ruins of an early-1900s silver-mining settlement and mill complex in the Pioneer Mountains. Reaching it involves forest roads and a walk, so seasonal conditions matter.', 'limited', 'https://visitmt.com/stories/montana-ghost-town-tour', null, 'America/Denver', now()),
  ('Marysville Historic Mining Town', 'marysville-historic-mining-town', 'weird-history', 46.75052, -112.30123, 'Marysville', 'MT', 'A once-booming gold town that never vanished completely; historic structures and mining remnants remain mixed among occupied homes. View respectfully from public roads.', 'roadside', 'https://visitmt.com/stories/montana-ghost-town-tour', null, 'America/Denver', now()),
  ('Rimini Ghost Town', 'rimini-ghost-town', 'weird-history', 46.48799, -112.24668, 'Rimini', 'MT', 'A semi-abandoned mining settlement west of Helena where old cabins, mine-era buildings, and modern residences coexist. Many structures are private, so this is primarily a public-road stop.', 'roadside', 'https://visitmt.com/stories/montana-ghost-town-tour', null, 'America/Denver', now()),
  ('Coloma — Mystery Camp of the Garnet Range', 'coloma-mystery-camp-of-the-garnet-range', 'weird-history', 46.84299, -113.38063, 'Drummond', 'MT', 'Scattered ruins of a little-documented mining camp near Garnet, sometimes called one of the range’s mystery towns. Access is rough and involves walking to fragile remains.', 'limited', 'https://visitmt.com/stories/montana-ghost-town-tour', null, 'America/Denver', now()),
  ('Pony Historic Mining Town', 'pony-historic-mining-town', 'weird-history', 45.65845, -111.8945, 'Pony', 'MT', 'A living community wrapped around the remains of a once-rich gold-mining town, with historic commercial buildings, cabins, and mine-era remnants still visible.', 'roadside', 'https://visitmt.com/stories/montana-ghost-town-tour', null, 'America/Denver', now()),
  ('Virginia City', 'virginia-city', 'museums', 45.2941, -111.94202, 'Virginia City', 'MT', 'A territorial gold-rush town preserved as a National Historic Landmark, packed with original storefronts, boardwalks, saloons, and museum collections.', 'open', 'https://virginiacitymt.com/', null, 'America/Denver', now()),
  ('Nevada City', 'nevada-city', 'museums', 45.30687, -111.96748, 'Nevada City', 'MT', 'A reconstructed and preserved mining-era town filled with relocated historic buildings, period artifacts, and living-history programming just west of Virginia City.', 'limited', 'https://virginiacitymt.com/', null, 'America/Denver', now()),
  ('Big Hole National Battlefield', 'big-hole-national-battlefield', 'weird-history', 45.64101, -113.6433, 'Wisdom', 'MT', 'A Nez Perce War battlefield and memorial landscape interpreting the August 1877 battle and the people who fought and died there. Treat the site as a place of remembrance.', 'open', 'https://www.nps.gov/biho/', null, 'America/Denver', now()),
  ('Anaconda Smoke Stack State Park', 'anaconda-smoke-stack-state-park', 'weird-history', 46.12319, -112.93143, 'Anaconda', 'MT', 'A 585-foot smelter stack dominating the valley above Anaconda, preserved as a monument to Montana’s copper-smelting era. The stack itself is not open for climbing.', 'roadside', 'https://fwp.mt.gov/stateparks/anaconda-smoke-stack', null, 'America/Denver', now()),
  ('Berkeley Pit Viewing Stand', 'berkeley-pit-viewing-stand', 'roadside-oddities', 46.01187, -112.51947, 'Butte', 'MT', 'A viewing platform over the enormous former open-pit copper mine now filled with acidic, metal-laden water—one of Butte’s starkest industrial landmarks.', 'limited', 'https://berkeleypitmt.com/', null, 'America/Denver', now()),
  ('Granite Mountain–Speculator Mine Memorial', 'granite-mountain-speculator-mine-memorial', 'weird-history', 46.02664, -112.52364, 'Butte', 'MT', 'A hilltop memorial overlooking Butte dedicated to the 168 miners killed in the 1917 Granite Mountain–Speculator fire, one of the deadliest hard-rock mining disasters in U.S. history.', 'open', 'https://granitemine.org/', null, 'America/Denver', now()),
  ('World Museum of Mining', 'world-museum-of-mining', 'weird-history', 46.00937, -112.56968, 'Butte', 'MT', 'A sprawling mining museum built around an actual mine yard, with a recreated 1890s mining town and underground mine-tour options.', 'limited', 'https://miningmuseum.org/', null, 'America/Denver', now()),
  ('Copper King Mansion', 'copper-king-mansion', 'weird-history', 46.01389, -112.53889, 'Butte', 'MT', 'William A. Clark’s lavish 34-room Victorian mansion, preserved with elaborate woodwork, stained glass, and period interiors. Tours and lodging operate on set schedules.', 'limited', 'https://thecopperkingmansion.com/', null, 'America/Denver', now()),
  ('Dumas Brothel', 'dumas-brothel', 'weird-history', 46.01072, -112.54257, 'Butte', 'MT', 'A surviving red-light-district brothel building dating to 1890. The property now operates through limited tours and special events, including paranormal-themed events.', 'limited', 'https://dumasbrothel.com/', null, 'America/Denver', now()),
  ('Our Lady of the Rockies', 'our-lady-of-the-rockies', 'weird-history', 46.00039, -112.44637, 'Butte', 'MT', 'A 90-foot illuminated statue standing high on the Continental Divide above Butte. Public access to the mountaintop is by scheduled tour rather than by driving the private access road.', 'limited', 'https://ourladyoftherockies.org/', null, 'America/Denver', now()),
  ('Old Montana Prison', 'old-montana-prison', 'weird-history', 46.39267, -112.73615, 'Deer Lodge', 'MT', 'Montana’s former territorial and state prison, retaining cell blocks, yards, towers, and execution-era history. The complex also hosts occasional paranormal tours and events.', 'open', 'https://pcmaf.org/old-montana-prison/', null, 'America/Denver', now()),
  ('Grant-Kohrs Ranch National Historic Site', 'grant-kohrs-ranch-national-historic-site', 'weird-history', 46.41359, -112.7467, 'Deer Lodge', 'MT', 'A preserved cattle-baron ranch interpreting the open-range era through original buildings, collections, livestock, and working-ranch demonstrations.', 'open', 'https://www.nps.gov/grko/', null, 'America/Denver', now()),
  ('Washoe Theatre', 'washoe-theatre', 'weird-history', 46.12781, -112.95321, 'Anaconda', 'MT', 'An ornate 1936 Art Deco movie palace with elaborate murals, lighting, and decorative interiors that remains a functioning theater.', 'open', 'https://washoetheatre.com/', null, 'America/Denver', now()),
  ('Ringing Rocks', 'ringing-rocks', 'roadside-oddities', 45.94327, -112.23893, 'Whitehall', 'MT', 'A boulder field where many rocks produce bell-like metallic tones when struck. BLM recommends a high-clearance vehicle for the rough final approach.', 'open', 'https://www.blm.gov/visit/ringing-rocks', null, 'America/Denver', now()),
  ('Merry Widow Health Mine', 'merry-widow-health-mine', 'roadside-oddities', 46.27132, -112.26362, 'Basin', 'MT', 'An operating underground radon ''health mine,'' a surviving example of an unusual regional wellness tradition. Included as cultural curiosity, not medical advice; radon exposure is a known lung-cancer risk.', 'limited', 'https://merrywidowhealthmine.com/', null, 'America/Denver', now()),
  ('Free Enterprise Radon Health Mine', 'free-enterprise-radon-health-mine', 'roadside-oddities', 46.27166, -112.15401, 'Boulder', 'MT', 'A privately operated radon mine offering underground and surface-room visits by arrangement. It is historically unusual, but radon exposure is an established health risk; do not treat promotional health claims as medical guidance.', 'private', 'https://www.radonmine.com/', null, 'America/Denver', now()),
  ('Sluice Boxes State Park', 'sluice-boxes-state-park', 'roadside-oddities', 47.212, -110.935, 'Belt', 'MT', 'A rugged limestone canyon cut by Belt Creek, with abandoned railroad grades, tunnels, cliffs, and mining remnants. Check current trail advisories before entering the canyon.', 'open', 'https://fwp.mt.gov/stateparks/sluice-boxes', null, 'America/Denver', now()),
  ('Milltown State Park', 'milltown-state-park', 'weird-history', 46.87129, -113.89816, 'Milltown', 'MT', 'A restored river-confluence landscape created after removal of the contaminated Milltown Dam and reservoir, with interpretation of one of Montana’s largest Superfund cleanups.', 'open', 'https://fwp.mt.gov/stateparks/milltown', null, 'America/Denver', now()),
  ('Lewis & Clark Caverns State Park', 'lewis-clark-caverns-state-park', 'roadside-oddities', 45.82289, -111.85082, 'Whitehall', 'MT', 'A major limestone cave system filled with stalactites, stalagmites, columns, and winding passages. Cave entry is by guided tour during the operating season.', 'limited', 'https://fwp.mt.gov/lewis-and-clark-caverns', null, 'America/Denver', now()),
  ('Beaverhead Rock State Park', 'beaverhead-rock-state-park', 'weird-history', 45.38333, -112.4609, 'Dillon', 'MT', 'A distinctive rock formation recognized by Sacagawea as a landmark near her homeland during the Lewis and Clark Expedition. The formation is primarily viewed from designated pullouts.', 'roadside', 'https://fwp.mt.gov/stateparks/beaverhead-rock', null, 'America/Denver', now()),
  ('Clark’s Lookout State Park', 'clarks-lookout-state-park', 'weird-history', 45.235, -112.634, 'Dillon', 'MT', 'A short climb to the limestone knob where William Clark took compass readings in 1805, with a broad view over the Beaverhead Valley.', 'limited', 'https://fwp.mt.gov/clarks-lookout', null, 'America/Denver', now()),
  ('Madison Buffalo Jump State Park', 'madison-buffalo-jump-state-park', 'weird-history', 45.79431, -111.47197, 'Three Forks', 'MT', 'A high cliff used for communal bison hunting for thousands of years. Trails and interpretation explain the archaeological landscape and traditional hunting system.', 'open', 'https://fwp.mt.gov/stateparks/madison-buffalo-jump', null, 'America/Denver', now()),
  ('Missouri Headwaters State Park', 'missouri-headwaters-state-park', 'weird-history', 45.92013, -111.49989, 'Three Forks', 'MT', 'The confluence where the Jefferson, Madison, and Gallatin rivers form the Missouri River, with archaeological and Lewis and Clark history layered across the landscape.', 'open', 'https://fwp.mt.gov/stateparks/missouri-headwaters', null, 'America/Denver', now()),
  ('Travelers’ Rest State Park', 'travelers-rest-state-park', 'weird-history', 46.75306, -114.09007, 'Lolo', 'MT', 'The only Lewis and Clark campsite archaeologically verified by physical evidence, preserving the expedition’s September 1805 and June 1806 camp area.', 'open', 'https://fwp.mt.gov/stateparks/travelers-rest', null, 'America/Denver', now()),
  ('Fort Owen State Park', 'fort-owen-state-park', 'weird-history', 46.51948, -114.09705, 'Stevensville', 'MT', 'Remains of an early trading post and settlement site in the Bitterroot Valley, preserving adobe and masonry traces from one of western Montana’s earliest non-Indigenous settlements.', 'open', 'https://fwp.mt.gov/stateparks/fort-owen', null, 'America/Denver', now()),
  ('Crystal Park', 'crystal-park', 'roadside-oddities', 45.48826, -113.09421, 'Polaris', 'MT', 'A designated Forest Service digging area where visitors can search for quartz crystals in decomposed granite. Snow and mountain-road conditions make access seasonal.', 'limited', 'https://www.fs.usda.gov/Internet/FSE_DOCUMENTS/fseprd1088683.pdf', null, 'America/Denver', now()),
  ('Earthquake Lake Visitor Center', 'earthquake-lake-visitor-center', 'weird-history', 44.83073, -111.42699, 'West Yellowstone', 'MT', 'Interpretive center overlooking the lake created when a magnitude 7.3 earthquake triggered a massive landslide across the Madison River in 1959.', 'limited', 'https://www.fs.usda.gov/r01/custergallatin/recreation/earthquake-lake-visitor-center', null, 'America/Denver', now()),
  ('Refuge Point Trail', 'refuge-point-trail', 'weird-history', 44.86826, -111.35859, 'West Yellowstone', 'MT', 'A trail through the 1959 Hebgen Lake earthquake disaster area to the high ground where survivors gathered after the landslide and flooding.', 'limited', 'https://www.fs.usda.gov/r01/custergallatin/recreation/earthquake-lake-visitor-center', null, 'America/Denver', now()),
  ('Roosevelt Arch', 'roosevelt-arch', 'weird-history', 45.02948, -110.7087, 'Gardiner', 'MT', 'The monumental stone arch at Yellowstone’s North Entrance, dedicated by President Theodore Roosevelt in 1903 and still spanning the historic gateway road.', 'open', 'https://www.nps.gov/places/000/roosevelt-arch.htm', null, 'America/Denver', now()),
  ('Museum of the Rockies', 'museum-of-the-rockies', 'museums', 45.65886, -111.04468, 'Bozeman', 'MT', 'A major paleontology museum with one of the world’s important dinosaur collections, including extensive Tyrannosaurus and Triceratops material from Montana.', 'open', 'https://museumoftherockies.org/', null, 'America/Denver', now()),
  ('American Computer & Robotics Museum', 'american-computer-robotics-museum', 'museums', 45.65935, -111.05497, 'Bozeman', 'MT', 'A compact museum tracing thousands of years of information technology, from writing and mechanical calculation to early computers, robotics, and space-era hardware.', 'open', 'https://acrmuseum.org/', null, 'America/Denver', now()),
  ('Gallatin History Museum', 'gallatin-history-museum', 'weird-history', 45.67967, -111.04221, 'Bozeman', 'MT', 'A local-history museum inside the former Gallatin County jail, retaining old cells and a hanging-gallows area alongside exhibits on regional history.', 'open', 'https://gallatinhistorymuseum.org/', null, 'America/Denver', now()),
  ('Yellowstone Gateway Museum', 'yellowstone-gateway-museum', 'weird-history', 45.66404, -110.56436, 'Livingston', 'MT', 'A regional museum covering Yellowstone tourism, railroad history, Indigenous history, transportation, and the often-overlooked stories of Park County.', 'open', 'https://yellowstonegatewaymuseum.org/', null, 'America/Denver', now()),
  ('Livingston Depot Center', 'livingston-depot-center', 'weird-history', 45.66174, -110.56296, 'Livingston', 'MT', 'A grand 1902 Northern Pacific Railway depot built as a gateway to Yellowstone, now housing seasonal museum exhibits inside its restored historic interior.', 'limited', 'https://livingstondepot.org/', null, 'America/Denver', now()),
  ('Original Governor’s Mansion', 'original-governors-mansion', 'weird-history', 46.58782, -112.03513, 'Helena', 'MT', 'A preserved Queen Anne mansion used by Montana governors from 1913 to 1959, offering a close look at political and domestic life from the early statehood era.', 'limited', 'https://mhs.mt.gov/education/tours', null, 'America/Denver', now()),
  ('Montana Heritage Center', 'montana-heritage-center', 'museums', 46.58725, -112.01598, 'Helena', 'MT', 'Montana’s major state-history museum and collections center, newly opened in 2025 with expanded exhibits covering the state’s people, archaeology, art, and material culture.', 'open', 'https://mhs.mt.gov/', null, 'America/Denver', now()),
  ('Reeder’s Alley', 'reeders-alley', 'weird-history', 46.5849, -112.0435, 'Helena', 'MT', 'A narrow brick-and-stone workers’ neighborhood dating to Helena’s mining boom, preserving some of the city’s oldest residential structures and a pioneer cabin.', 'open', 'https://www.helenahistory.org/reeders_alley.htm', null, 'America/Denver', now()),
  ('Guardian of the Gulch Fire Tower', 'guardian-of-the-gulch-fire-tower', 'weird-history', 46.58524, -112.04098, 'Helena', 'MT', 'A tall 1870s fire-watch tower built after devastating early Helena fires. The landmark still stands above Last Chance Gulch and is visible from surrounding streets and trails.', 'roadside', 'https://www.helenahistory.org/fire_tower.htm', null, 'America/Denver', now()),
  ('Cathedral of Saint Helena', 'cathedral-of-saint-helena', 'roadside-oddities', 46.59013, -112.03362, 'Helena', 'MT', 'A towering Gothic Revival cathedral modeled after European church architecture, with twin spires, carved stonework, and an extensive stained-glass interior.', 'open', 'https://www.sthelenas.org/', null, 'America/Denver', now()),
  ('Archie Bray Foundation', 'archie-bray-foundation', 'roadside-oddities', 46.614, -112.08269, 'Helena', 'MT', 'A former brickworks transformed into an internationally known ceramics center, where kilns, brick ruins, studios, and outdoor ceramic installations cover the grounds.', 'open', 'https://archiebray.org/visit/', null, 'America/Denver', now()),
  ('Blackfoot Pathways: Sculpture in the Wild', 'blackfoot-pathways-sculpture-in-the-wild', 'roadside-oddities', 46.95494, -112.68171, 'Lincoln', 'MT', 'A free outdoor sculpture park where monumental contemporary works sit among forest, meadow, and remnants of Lincoln’s logging history. Grounds are generally open dawn to dusk.', 'open', 'https://www.sculptureinthewild.com/', null, 'America/Denver', now()),
  ('Gates of the Mountains Boat Tour', 'gates-of-the-mountains-boat-tour', 'roadside-oddities', 46.83205, -111.95195, 'Helena', 'MT', 'A boat route through sheer limestone canyon walls on the Missouri River, named by Meriwether Lewis when the cliffs appeared to open like gates.', 'limited', 'https://gatesofthemountains.com/', null, 'America/Denver', now()),
  ('First Peoples Buffalo Jump State Park', 'first-peoples-buffalo-jump-state-park', 'weird-history', 47.479, -111.525, 'Ulm', 'MT', 'One of North America’s largest known bison-jump complexes, preserving a long-used cultural landscape, archaeological deposits, trails, and an interpretive center.', 'open', 'https://fwp.mt.gov/stateparks/first-peoples-buffalo-jump', null, 'America/Denver', now()),
  ('Giant Springs State Park', 'giant-springs-state-park', 'roadside-oddities', 47.534, -111.227, 'Great Falls', 'MT', 'One of the country’s largest freshwater springs, where clear water gushes from the Madison Limestone beside the Missouri River. The tiny Roe River also runs through the park.', 'open', 'https://fwp.mt.gov/stateparks/giant-springs', null, 'America/Denver', now()),
  ('Lewis & Clark Interpretive Center', 'lewis-clark-interpretive-center', 'weird-history', 47.52969, -111.23407, 'Great Falls', 'MT', 'A major interpretive center overlooking the Missouri River, focused on the expedition’s difficult portage around the Great Falls and the wider Indigenous landscape.', 'open', 'https://www.fs.usda.gov/visit/destination/lewis-and-clark-national-historic-trail-interpretive-center', null, 'America/Denver', now()),
  ('Paris Gibson Square Museum of Art', 'paris-gibson-square-museum-of-art', 'weird-history', 47.50594, -111.2825, 'Great Falls', 'MT', 'A contemporary-art museum inside a massive 1896 sandstone school building, combining changing exhibitions with one of Great Falls’ most striking reused historic structures.', 'open', 'https://the-square.org/', null, 'America/Denver', now()),
  ('Malmstrom Air Force Base Museum & Air Park', 'malmstrom-air-force-base-museum-air-park', 'weird-history', 47.50629, -111.20033, 'Great Falls', 'MT', 'A military museum and outdoor aircraft display tied to Malmstrom’s strategic-air and intercontinental-ballistic-missile history. Base entry requirements can limit access, so verify current visitor procedures.', 'limited', 'https://www.malmstrom.af.mil/', null, 'America/Denver', now()),
  ('Old Fort Benton', 'old-fort-benton', 'weird-history', 47.82121, -110.6633, 'Fort Benton', 'MT', 'A reconstructed and interpreted fur-trade fort complex at the head of Missouri River navigation, built on the site of one of the Upper Missouri’s most important trading posts.', 'limited', 'https://fortbenton.com/', null, 'America/Denver', now()),
  ('Museum of the Northern Great Plains', 'museum-of-the-northern-great-plains', 'museums', 47.82457, -110.66688, 'Fort Benton', 'MT', 'A large collection of homestead, agricultural, industrial, and transportation machinery documenting how people worked the northern plains.', 'limited', 'https://fortbentonmuseums.com/', null, 'America/Denver', now()),
  ('Shep Memorial', 'shep-memorial', 'folklore', 47.81657, -110.66772, 'Fort Benton', 'MT', 'A statue and gravesite memorializing Shep, the sheepdog famous for waiting at the Fort Benton rail station for years after his owner’s coffin departed by train.', 'open', 'https://fortbenton.com/things-to-do/the-shep-memorial/', null, 'America/Denver', now()),
  ('Old Fort Benton Bridge', 'old-fort-benton-bridge', 'weird-history', 47.81664, -110.66605, 'Fort Benton', 'MT', 'A late-19th-century iron bridge preserved as a pedestrian landmark over the Missouri River, marking a major shift from ferry crossings to permanent transportation.', 'open', 'https://fortbenton.com/plan-your-visit/for-the-history-buff/', null, 'America/Denver', now()),
  ('Decision Point Overlook', 'decision-point-overlook', 'weird-history', 47.92494, -110.49851, 'Loma', 'MT', 'An overlook above the Missouri–Marias confluence where Lewis and Clark had to decide which river branch led toward the Continental Divide.', 'open', 'https://www.blm.gov/visit/decision-point-overlook', null, 'America/Denver', now()),
  ('Tower Rock State Park', 'tower-rock-state-park', 'roadside-oddities', 47.189, -111.81, 'Cascade', 'MT', 'A massive rock formation rising beside the Missouri River and Interstate 15, recorded by Meriwether Lewis as a prominent landmark on the expedition route.', 'open', 'https://fwp.mt.gov/stateparks/tower-rock', null, 'America/Denver', now()),
  ('Upper Musselshell Museum', 'upper-musselshell-museum', 'museums', 46.43523, -109.83129, 'Harlowton', 'MT', 'A two-building local museum mixing fossils, a full-size dinosaur display, ranch and railroad artifacts, and an old horse-drawn hearse among its eclectic collections.', 'limited', 'https://www.harlowtonmuseum.org/', null, 'America/Denver', now()),
  ('Harlowton Milwaukee Depot Museum', 'harlowton-milwaukee-depot-museum', 'weird-history', 46.4311, -109.8299, 'Harlowton', 'MT', 'A preserved Milwaukee Road depot interpreting the electric railroad that once crossed central Montana, including artifacts from Harlowton’s role as an electrification center.', 'limited', 'https://harlomilwdepot.org/', null, 'America/Denver', now()),
  ('Castle Museum', 'castle-museum', 'weird-history', 46.55089, -110.90091, 'White Sulphur Springs', 'MT', 'A stone mansion turned county museum, filled with local artifacts, vehicles, and furnishings. The museum also schedules ''Dark Side of the Springs'' programs and paranormal ghost-hunt events.', 'limited', 'https://visitmt.com/listing/castle-museum-102', null, 'America/Denver', now()),
  ('Tippet Rise Art Center', 'tippet-rise-art-center', 'roadside-oddities', 45.48112, -109.56225, 'Fishtail', 'MT', 'A vast ranch-based art center where enormous sculptures appear across open foothills beneath the Beartooths. Visits are seasonal and generally require advance reservations.', 'limited', 'https://tippetrise.org/', null, 'America/Denver', now()),
  ('Montana Vortex and House of Mystery', 'montana-vortex-and-house-of-mystery', 'roadside-oddities', 48.3823, -114.12307, 'Columbia Falls', 'MT', 'A classic gravity-hill-style roadside attraction built around tilted structures, optical effects, and claims of a local ''vortex.'' Treat the effects as entertainment rather than established physics anomalies.', 'limited', 'http://www.montanavortex.com/', null, 'America/Denver', now()),
  ('Miracle of America Museum', 'miracle-of-america-museum', 'museums', 47.68004, -114.116, 'Polson', 'MT', 'A sprawling Americana collection with hundreds of thousands of objects, historic buildings, aircraft, vehicles, machinery, homemade inventions, and an Area 51-themed display.', 'open', 'https://www.miracleofamericamuseum.org/', null, 'America/Denver', now()),
  ('Polson-Flathead Lake Museum', 'polson-flathead-lake-museum', 'cryptids', 47.6886, -114.1638, 'Polson', 'MT', 'A local-history museum with an exhibit on ''Nessie,'' the legendary Flathead Lake Monster, alongside homestead, transportation, and regional artifacts.', 'limited', 'http://www.polsonflatheadmuseum.org/', null, 'America/Denver', now()),
  ('Garden of One Thousand Buddhas', 'garden-of-one-thousand-buddhas', 'roadside-oddities', 47.18891, -114.08772, 'Arlee', 'MT', 'A Tibetan Buddhist peace garden arranged around hundreds of Buddha statues, prayer wheels, and the central Yum Chenmo figure in Montana’s Jocko Valley. Visit respectfully as an active sacred site.', 'limited', 'https://ewam.org/centers/garden-of-one-thousand-buddhas/', null, 'America/Denver', now()),
  ('St. Ignatius Mission', 'st-ignatius-mission', 'weird-history', 47.315, -114.10194, 'St. Ignatius', 'MT', 'A late-19th-century Catholic mission church on the Flathead Reservation, noted for dozens of large interior murals. It remains an active place of worship, so visit respectfully.', 'open', 'https://stignatiusmission.org/', null, 'America/Denver', now()),
  ('Ninepipes Museum of Early Montana', 'ninepipes-museum-of-early-montana', 'weird-history', 47.4397, -114.09583, 'Charlo', 'MT', 'A Mission Valley museum combining homestead and ranch history with wildlife displays, Indigenous cultural material, and regional collections near the Ninepipe wetlands.', 'limited', 'https://ninepipesmuseum.org/', null, 'America/Denver', now()),
  ('Historical Museum at Fort Missoula', 'historical-museum-at-fort-missoula', 'weird-history', 46.84382, -114.0629, 'Missoula', 'MT', 'A multi-building museum on the former Fort Missoula grounds, interpreting military history, the 1917–1918 alien-detention camp, and the WWII internment of Italian and Japanese nationals.', 'open', 'https://fortmissoulamuseum.org/', null, 'America/Denver', now()),
  ('Museum of Mountain Flying', 'museum-of-mountain-flying', 'museums', 46.91864, -114.08359, 'Missoula', 'MT', 'A small aviation museum devoted to mountain flying, smokejumping, and regional aircraft history, with historic planes and equipment near Missoula’s airport.', 'limited', 'https://www.museumofmountainflying.com/', null, 'America/Denver', now()),
  ('Ninemile Historic Remount Depot', 'ninemile-historic-remount-depot', 'weird-history', 47.08143, -114.39827, 'Huson', 'MT', 'A preserved Forest Service remount station where pack animals, equipment, and backcountry skills supported early ranger operations and firefighting.', 'limited', 'https://visitmt.com/listing/ninemile-historic-remount-depot', null, 'America/Denver', now()),
  ('Daly Mansion', 'daly-mansion', 'weird-history', 46.26751, -114.14245, 'Hamilton', 'MT', 'The grand Bitterroot Valley estate of copper magnate Marcus Daly, preserved with period rooms, formal grounds, and furnishings tied to Montana’s Copper Kings.', 'limited', 'https://dalymansion.org/', null, 'America/Denver', now()),
  ('Ravalli County Museum', 'ravalli-county-museum', 'weird-history', 46.2445, -114.1579, 'Hamilton', 'MT', 'A regional museum inside the former county courthouse, with collections spanning Indigenous history, settlement, mining, natural history, and Bitterroot Valley life.', 'open', 'https://ravallimuseum.org/', null, 'America/Denver', now()),
  ('Historic St. Mary’s Mission', 'historic-st-marys-mission', 'weird-history', 46.50806, -114.09528, 'Stevensville', 'MT', 'A preserved 19th-century mission complex at the site associated with the founding of Stevensville, with historic buildings, artifacts, and interpretation of the Bitterroot Valley’s layered history.', 'limited', 'https://saintmarysmission.org/', null, 'America/Denver', now()),
  ('Conrad Mansion Museum', 'conrad-mansion-museum', 'weird-history', 48.19704, -114.30331, 'Kalispell', 'MT', 'A richly preserved 1895 mansion with original family furnishings, elaborate woodwork, and unusual turn-of-the-century household technology.', 'limited', 'https://conradmansion.com/', null, 'America/Denver', now()),
  ('Northwest Montana History Museum', 'northwest-montana-history-museum', 'weird-history', 48.1977, -114.31067, 'Kalispell', 'MT', 'A regional-history museum in the old Central School, covering timber, railroads, Indigenous history, settlement, and the growth of the Flathead Valley.', 'open', 'https://www.nwmthistory.org/', null, 'America/Denver', now()),
  ('Tobacco Valley Historical Village', 'tobacco-valley-historical-village', 'weird-history', 48.87716, -115.05224, 'Eureka', 'MT', 'A collection of relocated pioneer-era buildings assembled into a walkable historical village, including cabins, school and commercial structures from the Tobacco Valley.', 'limited', 'https://visitnwmontana.com/our-story/our-village', null, 'America/Denver', now()),
  ('Stonehenge Air Museum', 'stonehenge-air-museum', 'museums', 48.7978, -114.88866, 'Fortine', 'MT', 'A private museum with a collection of historic military aircraft in an unusually remote setting. Visits are by advance appointment, and directions are supplied through the museum.', 'private', 'https://www.stonehengeairmuseum.org/', null, 'America/Denver', now()),
  ('Kootenai Falls Swinging Bridge', 'kootenai-falls-swinging-bridge', 'roadside-oddities', 48.45272, -115.76985, 'Troy', 'MT', 'A pedestrian suspension bridge above the Kootenai River near a broad series of powerful natural falls. The trail can be icy or hazardous in bad conditions.', 'open', 'https://www.fs.usda.gov/r01/kootenai/recreation/kootenai-falls-and-swinging-bridge', null, 'America/Denver', now()),
  ('Ross Creek Cedar Grove Scenic Area', 'ross-creek-cedar-grove-scenic-area', 'roadside-oddities', 48.20857, -115.91384, 'Troy', 'MT', 'A grove of enormous western red cedars, some centuries old, reached by a short interpretive trail in the Kootenai National Forest.', 'limited', 'https://data.visitmt.com/data/site/6967', null, 'America/Denver', now()),
