  ('Old Trail Museum', 'old-trail-museum', 'museums', 47.81245, -112.18363, 'Choteau', 'MT', 'A small museum complex combining local history with dinosaur fossils, paleontology exhibits, historic buildings, and displays tied to the Rocky Mountain Front.', 'limited', 'https://oldtrailmuseum.org/', null, 'America/Denver', now()),
  ('Montana Dinosaur Center', 'montana-dinosaur-center', 'museums', 47.97591, -112.3115, 'Bynum', 'MT', 'A paleontology center known for hands-on field programs, fossil preparation, and a long skeletal display of the sauropod Seismosaurus/Diplodocus.', 'limited', 'https://tmdinosaurcenter.org/', null, 'America/Denver', now()),
  ('Wahkpa Chu’gn Buffalo Jump', 'wahkpa-chugn-buffalo-jump', 'weird-history', 48.5597, -109.71282, 'Havre', 'MT', 'A deeply stratified archaeological bison-jump site beside Havre, preserving repeated Indigenous hunting occupations over thousands of years. Public access is by guided tour.', 'limited', 'https://visitmt.com/listing/wahkpa-chugn-buffalo-jump-archaeological-site', null, 'America/Denver', now()),
