  ('Fort Assinniboine Historic Site', 'fort-assinniboine-historic-site', 'weird-history', 48.49836, -109.80069, 'Havre', 'MT', 'Remnants and restored buildings from a massive 19th-century U.S. Army post established near the Canadian border. Tours interpret its complicated military and regional history.', 'limited', 'https://fortassinniboine.org/', null, 'America/Denver', now()),
  ('H. Earl Clack Memorial Museum', 'h-earl-clack-memorial-museum', 'museums', 48.55308, -109.69868, 'Havre', 'MT', 'A local museum with regional history, archaeological material, and dinosaur fossils from north-central Montana, including finds associated with the nearby Judith River Formation.', 'open', 'https://www.earlclackmuseumfoundation.org/', null, 'America/Denver', now()),
  ('Rudyard Depot Museum', 'rudyard-depot-museum', 'museums', 48.5632, -110.55498, 'Rudyard', 'MT', 'A restored railroad depot and small-town museum complex combining homestead artifacts, vintage vehicles, local history, and dinosaur material from the Hi-Line.', 'limited', 'https://mtdinotrail.org/', null, 'America/Denver', now()),
