  ('Blaine County Museum', 'blaine-county-museum', 'weird-history', 48.59084, -109.23158, 'Chinook', 'MT', 'A regional museum with major interpretation of the Bear Paw Battlefield and Nez Perce War alongside homestead, Indigenous, military, and dinosaur history.', 'open', 'https://blainecountymuseum.com/', null, 'America/Denver', now()),
  ('Bear Paw Battlefield', 'bear-paw-battlefield', 'weird-history', 48.37788, -109.21335, 'Chinook', 'MT', 'The site where the 1877 Nez Perce flight ended after a five-day battle and siege. The National Park Service interprets the landscape as part of Nez Perce National Historical Park.', 'open', 'https://www.nps.gov/nepe/learn/historyculture/bear-paw-battlefield.htm', null, 'America/Denver', now()),
