  ('Great Plains Dinosaur Museum & Field Station', 'great-plains-dinosaur-museum-field-station', 'museums', 48.36041, -107.86778, 'Malta', 'MT', 'A fossil-focused museum and field station featuring dinosaurs and other prehistoric animals from northern Montana, with seasonal digs and preparation work.', 'limited', 'https://greatplainsdinosaurs.org/', null, 'America/Denver', now()),
  ('Fort Peck Interpretive Center', 'fort-peck-interpretive-center', 'museums', 48.00979, -106.42142, 'Fort Peck', 'MT', 'An interpretive center beside Fort Peck Dam combining Missouri River ecology, dam construction, and paleontology—including fossils from the surrounding badlands.', 'limited', 'https://www.fws.gov/refuge/charles-m-russell/fort-peck-interpretive-center', null, 'America/Denver', now()),
  ('Garfield County Museum', 'garfield-county-museum', 'museums', 47.32492, -106.90897, 'Jordan', 'MT', 'A small eastern Montana museum with local-history collections and significant dinosaur fossils from the Hell Creek Formation surrounding Jordan.', 'limited', 'https://mtdinotrail.org/', null, 'America/Denver', now()),
  ('Fort Peck Dam', 'fort-peck-dam', 'roadside-oddities', 48.00227, -106.41766, 'Fort Peck', 'MT', 'A colossal earth-filled dam built during the New Deal, stretching across the Missouri River and creating Fort Peck Lake. Its scale and remote setting make it a striking engineering stop.', 'open', 'https://www.nwo.usace.army.mil/Missions/Dam-and-Lake-Projects/Montana/Fort-Peck/', null, 'America/Denver', now()),
  ('Hell Creek State Park', 'hell-creek-state-park', 'roadside-oddities', 47.6164, -106.88692, 'Fort Peck', 'MT', 'A remote park on Fort Peck Lake surrounded by the Hell Creek Formation, the same fossil-rich rocks that have produced famous dinosaurs from the final age of the Cretaceous.', 'limited', 'https://fwp.mt.gov/stateparks/hell-creek', null, 'America/Denver', now()),
