  ('Frontier Gateway Museum', 'frontier-gateway-museum', 'weird-history', 47.12488, -104.68952, 'Glendive', 'MT', 'A regional museum with pioneer buildings, transportation artifacts, local history, and fossil material from the surrounding badlands.', 'limited', 'https://mtdinotrail.org/', null, 'America/Denver', now()),
  ('Glendive Dinosaur & Fossil Museum', 'glendive-dinosaur-fossil-museum', 'museums', 47.12513, -104.69123, 'Glendive', 'MT', 'A large private dinosaur-and-fossil museum presenting its exhibits through a biblical young-earth creationist framework. That interpretation differs from mainstream scientific dating of Earth and the fossil record.', 'limited', 'https://creationtruth.org/', null, 'America/Denver', now()),
  ('Carter County Museum', 'carter-county-museum', 'museums', 45.89099, -104.54648, 'Ekalaka', 'MT', 'Montana’s first county museum, with important dinosaur fossils, local-history collections, and displays tied to the fossil-rich badlands of southeastern Montana.', 'limited', 'https://cartercountymuseum.org/', null, 'America/Denver', now()),
  ('Medicine Rocks State Park', 'medicine-rocks-state-park', 'roadside-oddities', 46.0455, -104.45839, 'Ekalaka', 'MT', 'A surreal landscape of weather-carved sandstone pillars, holes, arches, and knobs that Theodore Roosevelt once described after visiting the area as a young rancher.', 'open', 'https://fwp.mt.gov/stateparks/medicine-rocks', null, 'America/Denver', now()),
  ('Prairie County Museum & Evelyn Cameron Gallery', 'prairie-county-museum-evelyn-cameron-gallery', 'museums', 46.7927, -105.313, 'Terry', 'MT', 'A small-town museum and photography gallery with homestead artifacts, Evelyn Cameron images, and odd local relics including a famously elaborate steam-heated outhouse.', 'limited', 'https://www.pcmuseum.org/', null, 'America/Denver', now()),
  ('Terry Badlands Overlook', 'terry-badlands-overlook', 'roadside-oddities', 46.83069, -105.39334, 'Terry', 'MT', 'A rough-road overlook into the eroded Terry Badlands, a maze of sandstone ridges, hoodoos, and coulees. Road conditions vary sharply with weather; high-clearance travel is prudent.', 'limited', 'https://www.blm.gov/site-page/programs-national-conservation-lands-montana-dakotas-terry-badlands-wsa', null, 'America/Denver', now()),
