  ('WaterWorks Art Museum', 'waterworks-art-museum', 'weird-history', 46.40627, -105.86873, 'Miles City', 'MT', 'A contemporary-art museum housed inside a former water-treatment plant, preserving industrial architecture while using the old facility as galleries and creative space.', 'open', 'https://www.waterworksartmuseum.org/', null, 'America/Denver', now()),
  ('Moss Mansion', 'moss-mansion', 'weird-history', 45.77964, -108.51604, 'Billings', 'MT', 'A 1903 mansion designed by Henry Janeway Hardenbergh, preserved with original family furnishings, decorative arts, and elaborate period interiors.', 'open', 'https://mossmansion.com/', null, 'America/Denver', now()),
  ('Western Heritage Center', 'western-heritage-center', 'weird-history', 45.78065, -108.50583, 'Billings', 'MT', 'A regional museum in the historic Parmly Billings Memorial Library, with changing exhibits on Yellowstone River Valley communities, material culture, and overlooked local stories.', 'open', 'https://www.ywhc.org/', null, 'America/Denver', now()),
  ('Yellowstone County Museum', 'yellowstone-county-museum', 'weird-history', 45.80251, -108.53806, 'Billings', 'MT', 'A compact museum near the airport built around a historic log cabin, holding tens of thousands of artifacts from Yellowstone County and the northern plains.', 'open', 'https://www.yellowstonecountymuseum.org/', null, 'America/Denver', now()),
  ('Pictograph Cave State Park', 'pictograph-cave-state-park', 'weird-history', 45.738, -108.433, 'Billings', 'MT', 'A three-cave archaeological complex where generations of Indigenous people left pictographs and other cultural material over thousands of years. Stay on designated trails and do not touch rock art.', 'open', 'https://fwp.mt.gov/stateparks/pictograph-cave', null, 'America/Denver', now()),
  ('Yellowstone Kelly Interpretive Site', 'yellowstone-kelly-interpretive-site', 'weird-history', 45.79815, -108.49375, 'Billings', 'MT', 'A hilltop gravesite and interpretive overlook for frontier scout Luther ''Yellowstone'' Kelly, with broad views over Billings and the Yellowstone Valley.', 'open', 'https://www.visitbillings.com/history/yellowstone-kelly-interpretive-site/', null, 'America/Denver', now()),
  ('Chief Plenty Coups State Park', 'chief-plenty-coups-state-park', 'weird-history', 45.427, -108.549, 'Pryor', 'MT', 'The preserved home, farmstead, grave, and sacred spring of Chief Plenty Coups of the Apsáalooke (Crow) Nation. The site is a National Historic Landmark and should be visited respectfully.', 'open', 'https://fwp.mt.gov/stateparks/chief-plenty-coups', null, 'America/Denver', now()),
  ('Little Bighorn Battlefield National Monument', 'little-bighorn-battlefield-national-monument', 'weird-history', 45.56575, -107.42729, 'Crow Agency', 'MT', 'A memorial landscape interpreting the 1876 Battle of the Little Bighorn, including the Custer battlefield, Indian Memorial, military cemetery, and sites connected to Lakota, Cheyenne, and Arapaho combatants.', 'open', 'https://www.nps.gov/libi/', null, 'America/Denver', now()),
  ('Rosebud Battlefield State Park', 'rosebud-battlefield-state-park', 'weird-history', 45.22031, -106.9759, 'Busby', 'MT', 'The large landscape of the June 1876 Battle of the Rosebud, where Lakota and Cheyenne forces fought General George Crook’s troops before the Little Bighorn campaign. The final approach includes unpaved road.', 'open', 'https://fwp.mt.gov/stateparks/rosebud-battlefield', null, 'America/Denver', now()),
  ('Pompeys Pillar National Monument', 'pompeys-pillar-national-monument', 'weird-history', 45.99552, -108.00539, 'Pompeys Pillar', 'MT', 'A sandstone pillar carrying centuries of Indigenous markings as well as William Clark’s 1806 carved signature—the only surviving in-place physical evidence from the Lewis and Clark Expedition open to the public.', 'limited', 'https://www.blm.gov/visit/pompeys-pillar-national-monument', null, 'America/Denver', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as montana from public.stops where state = 'MT';
